//! A bounded work queue with cancellation support.
//!
//! The queue has a fixed capacity. Producers block when the queue is full,
//! consumers block when the queue is empty. Cancellation is cooperative:
//! a `CancellationToken` can be used to wake blocked producers/consumers so
//! they return an error instead of waiting forever.

use std::collections::VecDeque;
use std::fmt;
use std::sync::{Arc, Condvar, Mutex};

/// Error returned by queue operations.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum QueueError {
    /// The operation was cancelled before it could complete.
    Cancelled,
    /// The queue was shut down; no more items can be sent.
    Closed,
}

impl fmt::Display for QueueError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            QueueError::Cancelled => write!(f, "operation cancelled"),
            QueueError::Closed => write!(f, "queue closed"),
        }
    }
}

impl std::error::Error for QueueError {}

/// A handle used to cancel pending operations on a queue.
///
/// Cheap to clone. Cancellation is "sticky": once cancelled, all subsequent
/// operations on queues sharing this token also fail immediately.
#[derive(Clone, Default)]
pub struct CancellationToken {
    inner: Arc<(Mutex<bool>, Condvar)>,
}

impl CancellationToken {
    pub fn new() -> Self {
        Self {
            inner: Arc::new((Mutex::new(false), Condvar::new())),
        }
    }

    /// Cancel the token. Wakes all waiters; future operations fail fast.
    pub fn cancel(&self) {
        let (lock, cv) = &*self.inner;
        let mut cancelled = lock.lock().unwrap();
        *cancelled = true;
        cv.notify_all();
    }

    /// Returns true if the token has been cancelled.
    pub fn is_cancelled(&self) -> bool {
        *self.inner.0.lock().unwrap()
    }

    fn wait(&self) -> bool {
        let (lock, cv) = &*self.inner;
        let mut cancelled = lock.lock().unwrap();
        while !*cancelled {
            cancelled = cv.wait(cancelled).unwrap();
        }
    }
}
